<template><div class="pattern-management-tools"><button @click="open('flow')">流程管理</button><button @click="open('urgency')">紧急程度设置</button><div v-if="mode" class="modal-mask"><section class="modal management-dialog" :class="{compact:mode==='task'||mode==='urgency'}"><header class="modal-head"><h3>{{mode==='flow'?'流程管理':mode==='urgency'?'紧急程度设置':'任务信息'}}</h3><button class="x" :disabled="busy" @click="mode=''">×</button></header><div class="modal-body"><p v-if="error" role="alert">{{error}}</p><template v-if="data"><template v-if="mode==='flow'"><p>流程任务控制填写区，二级状态用于阶段内分类；审核阶段及先后顺序受系统规则保护。</p><div class="management-scroll"><table><thead><tr><th>序号</th><th>流程名称</th><th>待纸样</th><th>流程任务</th><th>二级状态</th><th>作业时效(小时)</th><th>跟进人</th><th>同步到协同端</th></tr></thead><tbody><tr v-for="(s,i) in data.config.stages" :key="s.key"><td>{{i+1}}</td><td><input class="input" v-model="s.label" maxlength="30"/></td><td><input type="radio" name="wait-paper" :checked="s.wait_paper" @change="data.config.stages.forEach(t=>t.wait_paper=t.key===s.key)"/></td><td><button @click="chooseTasks(s)">添加任务</button><div>{{(s.tasks||[]).map(t=>t==='富文本'?'业务要求':t).join('，')||'未选择'}}</div></td><td><button @click="addValue(s,'states','二级状态名称')">添加状态</button><button v-for="(v,j) in s.states||[]" :key="v" class="chip" @click="s.states.splice(j,1)">{{v}} ×</button></td><td><input class="input" type="number" min="1" max="8760" v-model.number="s.hours"/></td><td><button @click="addValue(s,'owners','跟进人姓名')">添加跟进人</button><button v-for="(v,j) in s.owners||[]" :key="v" class="chip" @click="s.owners.splice(j,1)">{{v}} ×</button></td><td><input type="checkbox" disabled/> 未接入</td></tr></tbody></table></div></template><template v-else-if="mode==='urgency'"><table><thead><tr><th>排序</th><th>紧急程度名称</th><th>目标小时</th><th>背景颜色</th><th>字体颜色</th><th>预览</th><th>操作</th></tr></thead><tbody><tr v-for="(u,i) in data.config.urgencies" :key="i"><td><button :disabled="!i" @click="move(i,-1)">↑</button><button :disabled="i===data.config.urgencies.length-1" @click="move(i,1)">↓</button></td><td><input class="input" v-model="u.name" maxlength="20"/></td><td><input class="input" type="number" v-model.number="u.hours"/></td><td><input type="color" v-model="u.background"/></td><td><input type="color" v-model="u.foreground"/></td><td><span class="urgency-preview" :style="{background:u.background,color:u.foreground}">{{u.name||'预览'}}</span></td><td><button @click="data.config.urgencies.splice(i,1)">删除</button></td></tr></tbody></table><button class="add-wide" @click="data.config.urgencies.push({name:'',hours:24,background:'#409eff',foreground:'#ffffff'})">添加紧急程度</button></template><template v-else-if="selected"><div class="task-summary"><img v-if="selected.image_url" :src="selected.image_url" @click="openImage(selected.image_url,selected.product_name)"/><div><b>{{selected.customer_style_no||selected.product_name}}</b><p>客户：{{selected.customer_name||'—'}}</p><p>版本：{{selected.version}}</p><p>当前流程：{{label(selected.current_stage)}}</p><p>流程流转需通过前置审核，请在填写页面保存并完成。</p></div></div><label>二级状态<select class="input" v-model="secondary"><option value="">未设置</option><option v-for="v in currentStage?.states||[]" :key="v">{{v}}</option></select></label><label>紧急程度<select class="input" v-model="urgency"><option value="">普通</option><option v-for="u in data.config.urgencies" :key="u.name">{{u.name}}</option></select></label><label>跟进人<input class="input" v-model="owner" list="pattern-followers" maxlength="100"/><datalist id="pattern-followers"><option v-for="name in currentStage?.owners||[]" :key="name" :value="name"/></datalist></label><div class="task-actions"><span>{{(currentStage?.tasks||[]).join('，')}}</span><button @click="$emit('fill',selected)">填写任务</button></div><textarea class="input" rows="4" v-model="note" maxlength="2000" placeholder="备注 / 本次调整说明"/><p v-for="(r,i) in data.config.tasks[selected.id]?.records||[]" :key="i">{{fmtTime(r.at)}} · {{r.by}} · {{r.secondary_status||''}} · {{r.urgency}}<br/>{{r.note}}</p></template></template></div><footer class="modal-foot"><button :disabled="busy" @click="mode=''">取消</button><button :disabled="busy||!data||mode==='task'&&(selected?.status==='done'||!note.trim())" @click="save">确定</button></footer></section></div></div></template>
<script setup>
import {ref,computed,onMounted} from 'vue';import {api} from '../api';import {fmtTime} from '../utils/time';import {openImage} from '../store/viewer';
const emit=defineEmits(['configured','fill']);const mode=ref(''),data=ref(null),busy=ref(false),error=ref(''),selected=ref(null),note=ref(''),owner=ref(''),urgency=ref(''),secondary=ref('');const currentStage=computed(()=>data.value?.config.stages.find(s=>s.key===selected.value?.current_stage));
const label=k=>data.value?.config.stages.find(s=>s.key===k)?.label||k;
const taskOptions=['物料详情','物料备注','成衣尺寸','工序表','外发工艺','生产要求','文件信息','业务要求'];
async function load(){data.value=await api.patternManagement();if(!data.value.config.stages.length)data.value.config.stages=data.value.stages.map(s=>({key:s.key,label:s.label,hours:72,tasks:[],states:[],owners:[],wait_paper:s.key==='pattern'}));data.value.config.urgencies.forEach(u=>{u.background||='#409eff';u.foreground||='#ffffff';});emit('configured',data.value.config);}
async function open(k){mode.value=k;error.value='';try{await load();}catch(e){error.value=e.message;}}
async function editTask(f){await open('task');selected.value=f;const task=data.value?.config.tasks[f.id]||{};owner.value=task.owner||'';urgency.value=task.urgency||'';secondary.value=task.secondary_status||'';note.value='';}
function addValue(s,key,title){const v=prompt(title);if(!v?.trim())return;s[key]||=[];if(!s[key].includes(v.trim()))s[key].push(v.trim());}
function chooseTasks(s){const v=prompt('选择填写内容（逗号分隔）：'+taskOptions.join('，'),(s.tasks||[]).map(t=>t==='富文本'?'业务要求':t).join('，'));if(v===null)return;const values=[...new Set(v.split(/[,，]/).map(v=>v.trim()).filter(Boolean))];if(values.some(v=>!taskOptions.includes(v)))return alert('请从列出的任务中选择');s.tasks=values.map(t=>t==='业务要求'?'富文本':t);}
function move(i,d){const a=data.value.config.urgencies;[a[i],a[i+d]]=[a[i+d],a[i]];}
async function save(){busy.value=true;error.value='';try{if(mode.value==='task')await api.followPattern(selected.value.id,{version:data.value.config.version,note:note.value,owner:owner.value,urgency:urgency.value,secondary_status:secondary.value});else await api.savePatternManagement(data.value.config);await load();mode.value='';}catch(e){error.value=e.message;}finally{busy.value=false;}}
onMounted(()=>load().catch(()=>{}));defineExpose({editTask});
</script><style scoped>.pattern-management-tools{display:flex;gap:8px}.pattern-management-tools>button{background:#168bfa;border:0;color:white;padding:8px 14px;border-radius:3px;cursor:pointer}.management-dialog{width:1500px;max-width:96vw;max-height:90vh}.management-dialog.compact{width:850px}.management-scroll{overflow:auto}table{width:100%;border-collapse:collapse}th,td{border:1px solid var(--line);padding:10px;font-size:12px;text-align:left}td .input{min-width:100px}td:nth-child(2) .input{min-width:170px}.chip{display:block;margin:6px 0}.urgency-preview{display:inline-block;padding:5px 9px;white-space:nowrap;border-radius:4px}.add-wide{width:100%;padding:10px;margin-top:10px}.task-summary{display:flex;gap:20px;margin-bottom:20px}.task-summary img{width:110px;height:140px;object-fit:contain;cursor:zoom-in}.management-dialog label{display:inline-block;margin:8px}.task-actions{padding:12px;background:var(--surface-2);margin:12px 0;display:flex;justify-content:space-between}[role=alert]{color:#d33}</style>
